import{_ as r,o as n,c as a,ai as t}from"./chunks/framework.Ai2o9gNv.js";const o="/assets/image_1.BvP7xj8K.png",s="/assets/image_2.DzYsxulY.png",p="/assets/image_3.f6V04jhj.png",_=JSON.parse('{"title":"分层架构设计-应用架构","description":"","frontmatter":{},"headers":[],"relativePath":"HarmonyOS 最佳实践/01-分层架构设计-应用架构/分层架构设计-应用架构.md","filePath":"HarmonyOS 最佳实践/01-分层架构设计-应用架构/分层架构设计-应用架构.md","lastUpdated":1750695195000,"__rawMarkdown":"# 分层架构设计-应用架构\\n\\nHarmonyOS 应用的分层架构设计基于一套代码工程，支持华为手机、PC/2in1 等 1+8 全场景设备，实现了“[一次开发，多端部署](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/foreword)”的开发理念。\\n\\nHarmonyOS 应用分层架构包括产品定制层、基础特性层和公共能力层，构建了清晰、高效、可扩展的设计架构。\\n\\n本文将从[逻辑模型](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-layered-architecture-design#section2075132511213)、[开发模型](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-layered-architecture-design#section1191910571522)和[部署模型](https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-layered-architecture-design#section1117721715317)分别介绍应用分层架构设计规则。\\n\\n## 逻辑模型\\n\\n**图 1** 分层架构逻辑模型  \\n![](./assets/image_1.png)\\n\\n- **产品定制层**\\n\\n  产品定制层专注于满足不同设备或使用场景的个性化需求，包括 UI 设计、资源和配置，以及特定场景的交互逻辑和功能特性。\\n\\n  产品定制层的功能模块独立运作，依赖基础特性层和公共能力层实现具体功能。\\n\\n  产品定制层作为应用的入口，是用户直接互动的界面。为了满足特定需求，产品定制层可以灵活调整和扩展，以适应各种使用场景。\\n\\n- **基础特性层**\\n\\n  基础特性层位于公共能力层之上，用于存放相对独立的功能 UI 和业务逻辑实现。每个功能模块都具备高内聚、低耦合、可定制的特点，支持产品的灵活部署。\\n\\n  基础特性层为产品定制层提供稳健且丰富的基础功能支持，包括 UI 组件和基础服务。公共能力层为其提供通用功能和服务。\\n\\n  为了增强系统的可扩展性和维护性，基础特性层对功能进行了模块化处理。例如，应用底部导航栏的每个选项都是一个独立的业务模块。\\n\\n- **公共能力层**\\n\\n  公共功能层存放公共基础能力，包括公共 UI 组件、数据管理、外部交互和工具库等共享功能。应用可调用这些公共能力。\\n\\n  公共能力层提供稳定可靠的功能支持，确保应用的稳定性和可维护性。\\n\\n  公共能力层包含以下组成部分：\\n\\n  - 公共 UI 组件：公共 UI 组件设计为通用且高度可复用，确保在不同应用程序模块间保持一致的用户体验。这些组件提供标准化、友好的界面，帮助开发者快速实现常见的用户交互需求，如提示、警告和加载状态显示，从而提高开发效率和用户满意度。\\n  - 数据管理：负责应用程序中数据的存储和访问，包括应用数据、系统数据等，提供了统一的数据管理接口，简化数据的读写操作。通过集中式的数据管理方式不仅使得数据的维护更为简单，而且能够保证数据的一致性和安全性。\\n  - 外部交互：外部交互负责应用程序与外部系统的交互，包括网络请求、文件 I/O、设备 I/O 等，提供统一的外部接口，简化应用程序与外部系统的交互。开发者可以方便地实现网络通信、数据存储和硬件接入，从而加速开发流程并保证程序的稳定性和性能。\\n  - 工具库：工具库提供一系列常用工具函数和类，如字符串处理、日期时间处理、加密解密、数据压缩解压等，帮助开发者提高效率和代码质量。\\n\\n## 开发模型\\n\\n**图 2** 分层架构开发模型  \\n![](./assets/image_2.png)\\n\\n- **产品定制层**\\n\\n  产品定制层的各个子目录会被编译成一个[Entry 类型的 HAP](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/hap-package)，作为应用的主入口。该层面向多种设备，集成相应功能和特性。产品定制层划分为多个功能模块，每个模块针对特定设备或使用场景设计，并根据产品需求进行功能和交互的定制开发。\\n\\n  说明\\n\\n  - 在产品定制层，开发者可以从不同设备对应的应用 UX 设计和功能两个维度，结合具体的业务场景，选择一次编译生成[相同或者不同的 HAP（或其组合）](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/introduction#%E9%83%A8%E7%BD%B2%E6%A8%A1%E5%9E%8B)。\\n  - 通过使用[定制多目标构建产物](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/ide-customized-multi-targets-and-products-guides)的定制功能，可以将应用所对应的 HAP 编译成各自的.app 文件，用于上架到应用市场。\\n\\n- **基础特性层**\\n\\n  在基础特性层中，功能模块根据部署需求被分为两类。对于需要通过 Ability 承载的功能，可以设计为[Feature 类型的 HAP](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/hap-package)，而对于不需要通过 Ability 承载的功能，根据是否需要实现按需加载，可以选择设计为[HAR](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/har-package)模块或者[HSP](https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/in-app-hsp)模块，编译后对应 HAR 包或者 HSP 包。\\n\\n- **公共能力层**\\n\\n  公共能力层的各子目录将编译成 HAR 包，仅产品定制层和基础特性层可依赖，不允许反向依赖。该层提取模块化公共基础能力，为上层提供标准接口和协议，提高复用率和开发效率。\\n\\n## 部署模型\\n\\n**图 3** 分层架构部署模型（不同设备的定制）  \\n![](./assets/image_3.png)\\n\\n应用程序（.app 文件）在流水线或应用市场上被解包为 n 个 Entry 类型的 HAP 和 n 个 Feature 类型的 HAP，根据设备类型和使用场景部署到不同设备，实现多端统一用户体验。\\n\\n说明\\n\\n当 Entry 类型的 HAP 和 Feature 类型的 HAP 被分发并部署到相应设备时，它们所依赖的 HSP 也会一同被分发并部署到相应设备上。\\n\\n在部署模型中，每个 Entry 类型的 HAP 代表了应用的入口点，而 Feature 类型的 HAP 则包含了应用的特定功能模块。允许应用能够以模块化的方式适配和部署，从而满足不同设备和场景的需求。\\n\\n部署模型优化了应用的组织结构，确保了应用在各种设备和场景中的一致性。通过根据设备类型和使用场景区分和部署不同的 HAP，用户在任何设备或场景中都能获得统一且高质量的体验。\\n"}'),c={name:"HarmonyOS 最佳实践/01-分层架构设计-应用架构/分层架构设计-应用架构.md"};function i(l,e,d,h,u,m){return n(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="分层架构设计-应用架构" tabindex="-1">分层架构设计-应用架构 <a class="header-anchor" href="#分层架构设计-应用架构" aria-label="Permalink to &quot;分层架构设计-应用架构&quot;">​</a></h1><p>HarmonyOS 应用的分层架构设计基于一套代码工程，支持华为手机、PC/2in1 等 1+8 全场景设备，实现了“<a href="https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/foreword" target="_blank" rel="noreferrer">一次开发，多端部署</a>”的开发理念。</p><p>HarmonyOS 应用分层架构包括产品定制层、基础特性层和公共能力层，构建了清晰、高效、可扩展的设计架构。</p><p>本文将从<a href="https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-layered-architecture-design#section2075132511213" target="_blank" rel="noreferrer">逻辑模型</a>、<a href="https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-layered-architecture-design#section1191910571522" target="_blank" rel="noreferrer">开发模型</a>和<a href="https://developer.huawei.com/consumer/cn/doc/best-practices/bpta-layered-architecture-design#section1117721715317" target="_blank" rel="noreferrer">部署模型</a>分别介绍应用分层架构设计规则。</p><h2 id="逻辑模型" tabindex="-1">逻辑模型 <a class="header-anchor" href="#逻辑模型" aria-label="Permalink to &quot;逻辑模型&quot;">​</a></h2><p><strong>图 1</strong> 分层架构逻辑模型<br><img src="'+o+'" alt=""></p><ul><li><p><strong>产品定制层</strong></p><p>产品定制层专注于满足不同设备或使用场景的个性化需求，包括 UI 设计、资源和配置，以及特定场景的交互逻辑和功能特性。</p><p>产品定制层的功能模块独立运作，依赖基础特性层和公共能力层实现具体功能。</p><p>产品定制层作为应用的入口，是用户直接互动的界面。为了满足特定需求，产品定制层可以灵活调整和扩展，以适应各种使用场景。</p></li><li><p><strong>基础特性层</strong></p><p>基础特性层位于公共能力层之上，用于存放相对独立的功能 UI 和业务逻辑实现。每个功能模块都具备高内聚、低耦合、可定制的特点，支持产品的灵活部署。</p><p>基础特性层为产品定制层提供稳健且丰富的基础功能支持，包括 UI 组件和基础服务。公共能力层为其提供通用功能和服务。</p><p>为了增强系统的可扩展性和维护性，基础特性层对功能进行了模块化处理。例如，应用底部导航栏的每个选项都是一个独立的业务模块。</p></li><li><p><strong>公共能力层</strong></p><p>公共功能层存放公共基础能力，包括公共 UI 组件、数据管理、外部交互和工具库等共享功能。应用可调用这些公共能力。</p><p>公共能力层提供稳定可靠的功能支持，确保应用的稳定性和可维护性。</p><p>公共能力层包含以下组成部分：</p><ul><li>公共 UI 组件：公共 UI 组件设计为通用且高度可复用，确保在不同应用程序模块间保持一致的用户体验。这些组件提供标准化、友好的界面，帮助开发者快速实现常见的用户交互需求，如提示、警告和加载状态显示，从而提高开发效率和用户满意度。</li><li>数据管理：负责应用程序中数据的存储和访问，包括应用数据、系统数据等，提供了统一的数据管理接口，简化数据的读写操作。通过集中式的数据管理方式不仅使得数据的维护更为简单，而且能够保证数据的一致性和安全性。</li><li>外部交互：外部交互负责应用程序与外部系统的交互，包括网络请求、文件 I/O、设备 I/O 等，提供统一的外部接口，简化应用程序与外部系统的交互。开发者可以方便地实现网络通信、数据存储和硬件接入，从而加速开发流程并保证程序的稳定性和性能。</li><li>工具库：工具库提供一系列常用工具函数和类，如字符串处理、日期时间处理、加密解密、数据压缩解压等，帮助开发者提高效率和代码质量。</li></ul></li></ul><h2 id="开发模型" tabindex="-1">开发模型 <a class="header-anchor" href="#开发模型" aria-label="Permalink to &quot;开发模型&quot;">​</a></h2><p><strong>图 2</strong> 分层架构开发模型<br><img src="'+s+'" alt=""></p><ul><li><p><strong>产品定制层</strong></p><p>产品定制层的各个子目录会被编译成一个<a href="https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/hap-package" target="_blank" rel="noreferrer">Entry 类型的 HAP</a>，作为应用的主入口。该层面向多种设备，集成相应功能和特性。产品定制层划分为多个功能模块，每个模块针对特定设备或使用场景设计，并根据产品需求进行功能和交互的定制开发。</p><p>说明</p><ul><li>在产品定制层，开发者可以从不同设备对应的应用 UX 设计和功能两个维度，结合具体的业务场景，选择一次编译生成<a href="https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/introduction#%E9%83%A8%E7%BD%B2%E6%A8%A1%E5%9E%8B" target="_blank" rel="noreferrer">相同或者不同的 HAP（或其组合）</a>。</li><li>通过使用<a href="https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/ide-customized-multi-targets-and-products-guides" target="_blank" rel="noreferrer">定制多目标构建产物</a>的定制功能，可以将应用所对应的 HAP 编译成各自的.app 文件，用于上架到应用市场。</li></ul></li><li><p><strong>基础特性层</strong></p><p>在基础特性层中，功能模块根据部署需求被分为两类。对于需要通过 Ability 承载的功能，可以设计为<a href="https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/hap-package" target="_blank" rel="noreferrer">Feature 类型的 HAP</a>，而对于不需要通过 Ability 承载的功能，根据是否需要实现按需加载，可以选择设计为<a href="https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/har-package" target="_blank" rel="noreferrer">HAR</a>模块或者<a href="https://developer.huawei.com/consumer/cn/doc/harmonyos-guides/in-app-hsp" target="_blank" rel="noreferrer">HSP</a>模块，编译后对应 HAR 包或者 HSP 包。</p></li><li><p><strong>公共能力层</strong></p><p>公共能力层的各子目录将编译成 HAR 包，仅产品定制层和基础特性层可依赖，不允许反向依赖。该层提取模块化公共基础能力，为上层提供标准接口和协议，提高复用率和开发效率。</p></li></ul><h2 id="部署模型" tabindex="-1">部署模型 <a class="header-anchor" href="#部署模型" aria-label="Permalink to &quot;部署模型&quot;">​</a></h2><p><strong>图 3</strong> 分层架构部署模型（不同设备的定制）<br><img src="'+p+'" alt=""></p><p>应用程序（.app 文件）在流水线或应用市场上被解包为 n 个 Entry 类型的 HAP 和 n 个 Feature 类型的 HAP，根据设备类型和使用场景部署到不同设备，实现多端统一用户体验。</p><p>说明</p><p>当 Entry 类型的 HAP 和 Feature 类型的 HAP 被分发并部署到相应设备时，它们所依赖的 HSP 也会一同被分发并部署到相应设备上。</p><p>在部署模型中，每个 Entry 类型的 HAP 代表了应用的入口点，而 Feature 类型的 HAP 则包含了应用的特定功能模块。允许应用能够以模块化的方式适配和部署，从而满足不同设备和场景的需求。</p><p>部署模型优化了应用的组织结构，确保了应用在各种设备和场景中的一致性。通过根据设备类型和使用场景区分和部署不同的 HAP，用户在任何设备或场景中都能获得统一且高质量的体验。</p>',17)])])}const A=r(c,[["render",i]]);export{_ as __pageData,A as default};
